@Component
@RequiredArgsConstructor
public class SistemaPermitidoValidator implements JobParametersValidator {

    private final P158Properties props;

    /** Equivale a PROCEDURE DIVISION USING W77-SIST-PARAM y al IF de 000-000-CHECA-DIA. */
    @Override
    public void validate(JobParameters params) throws JobParametersInvalidException {
        Long sistema = params.getLong("sistema");
        if (sistema == null || !props.sistemasPermitidos().contains(sistema.intValue())) {
            // STOP RUN tras escribir el mensaje en V00-REPORTE2 y en LJ
            throw new JobParametersInvalidException("EL P158 NO CORRE PARA ESTE SISTEMA");
        }
    }
}

@Bean
Job estadoCuentaPorContrato(JobRepository repo, SistemaPermitidoValidator validador,
                            Step inicializa,        // 100-010 .. 100-050: fechas, headers, catálogos S080
                            Step clasificaMovimientos,  // INPUT PROCEDURE 150-005-ORDENA-REGISTROS
                            Step imprimeListados,   // OUTPUT PROCEDURE 200-000-EJECUTA-IMPRESION
                            Step totalesYCierre) {  // TOTAL, CALL SYSTEM WFL, 12750-VALIDA-RESI170
    return new JobBuilder("S151P158", repo)
            .validator(validador)
            .start(inicializa)
            .next(clasificaMovimientos)
            .next(imprimeListados)
            .next(totalesYCierre)
            .build();
}

/**
 * El SORT intermedio se sustituye por una tabla de staging ordenada por la llave.
 * clasificaMovimientos escribe en ella (RELEASE) y imprimeListados la lee con
 * ORDER BY de los nueve campos de LlaveOrden (RETURN). 70000-CALCULA-ESPACIO
 * deja de ser necesario: el dimensionamiento lo hace la base de datos.
 */
@Bean
JdbcPagingItemReader<MovimientoOrdenado> lectorOrdenado(DataSource ds) {
    return new JdbcPagingItemReaderBuilder<MovimientoOrdenado>()
            .name("archOrd").dataSource(ds).pageSize(1000)
            .selectClause("SELECT *").fromClause("FROM P158_ARCH_ORD")
            .sortKeys(LlaveOrden.SORT_KEYS)        // LinkedHashMap con los 9 campos ASC
            .rowMapper(new MovimientoOrdenadoRowMapper())
            .build();
}

@Component
@RequiredArgsConstructor
public class TotalesYCierreTasklet implements Tasklet {

    private final JobLauncher launcher;
    private final Job listadoMovimientos;       // antes BEGIN JOB ... RUN P170 vía CALL SYSTEM WFL
    private final ArchivoResidencia residencia; // ATTRIBUTE RESIDENT OF I01-MOVIMIENTOS
    private final P158Properties props;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) throws Exception {
        int sistema = ctx.getStepContext().getJobParameters().get("sistema") instanceof Long l ? l.intValue() : 0;
        lanza("MOVXCONT", ctx);
        if (sistema == 500) {
            lanza("MOVXSCON", ctx);             // listado con subcuentas, solo sistema 500
        }
        // 12750-VALIDA-RESI170: WAIT (15) mientras el archivo no exista. En COBOL no hay tope.
        Path i01 = residencia.resuelve(props.tituloInmov(), ctx);
        Awaitility.await().pollInterval(Duration.ofSeconds(15))
                  .atMost(props.esperaMaximaP170())          // nuevo: tope configurable
                  .until(() -> Files.exists(i01));
        Files.delete(i01);                                  // OPEN INPUT ... CLOSE WITH PURGE
        return RepeatStatus.FINISHED;
    }

    private void lanza(String listado, ChunkContext ctx) throws Exception {
        launcher.run(listadoMovimientos, new JobParametersBuilder()
                .addString("listado", listado)
                .addLocalDate("fechaProceso", FechaProceso.de(ctx))
                .toJobParameters());
    }
}

/** 150-010-LEE-REGISTRO. Devuelve las acciones a realizar con un movimiento de LOG151. */
Acciones evalua(MovimientoLog151 m, int sistema) {
    boolean activo = m.funcion() == 1 && (m.status() == 1 || m.status() == 2)
            && (m.origen() == 1 || m.origen() == 3);                      // W77-REGACT
    int productos = (sistema == 87) ? m.agrupDesvProd() : m.producto();  // W77-PRODUCTOS
    boolean devolucionEspecial = (sistema == 407 || sistema == 408)
            && m.tipoProc() > 79 && m.tipoProc() < 90;

    // Punteo contra S500 (L07-DATOS). Se reproduce la precedencia real del IF de las
    // líneas 10803-10804: (sistema = 500 AND tipo = 40) OR tipo = 41 OR tipo = 42 OR tipo = 43.
    boolean excluyePunteo = (sistema == 500 && m.tipoProc() == 40)
            || m.tipoProc() == 41 || m.tipoProc() == 42 || m.tipoProc() == 43;
    boolean punteo = !devolucionEspecial
            && m.funcion() == 1 && m.status() == 1 && m.tipoProc() > 19
            && !excluyePunteo;

    // Envío al SORT: aquí el fuente sí usa paréntesis y la exclusión 40-43 es solo para 500.
    boolean alSort = !props.soloPunteo(sistema) && activo && !devolucionEspecial
            && !(sistema == 500 && m.tipoProc() > 39 && m.tipoProc() < 44);

    return new Acciones(productos, punteo, alSort);
}
// El lector termina con AT END o con el registro lógico de fin (A00-R01-FUNCION = 99).

/** 150-025-MUEVE-GRABA-SORT, armado de KEY-PRINC. */
LlaveOrden llaveDe(MovimientoLog151 m, int sistema, EstructuraSucursales est, int globCsi) {
    int moneda = (m.moneda() < 1 || m.moneda() > 99) ? 1 : m.moneda();  // saneo silencioso
    int subnodo = (m.sucProm() > 0)
            ? est.subnodoDe(m.sucProm())        // WKS-TAB-NOD-SUB(A00-R01-SUCPROM)
            : globCsi * 100;                    // sin sucursal promotora: CSI del job
    int tipoProd = (m.producto() == 66) ? 1 : 2;  // cuenta maestra primero en el listado
    int prod = (sistema == 408 || sistema == 407) ? m.producto() : 0;
    return new LlaveOrden(subnodo, m.sucProm(), tipoProd,
            String.format("%016d", m.contrato()), prod,
            m.instrumento(), m.sucOper(), m.cajaOper(), m.autS151());
}

public enum TipoContable { NINGUNO, CARGO, ABONO, NO_CONTABLE }   // W77-TIPOTRAN 0, 1, 2, 3

/** 150-100-TIPO-CONTAB sobre el catálogo de transacciones S080 cargado en memoria. */
TipoContable tipoContable(Transaccion t, int sistema, MovimientoLog151 m) {
    boolean devolucionDe500 = sistema == 407 && m.sistOrig() == 500;
    if (t.asEdocta() != 5 || devolucionDe500) {
        return switch (t.asAplsdo()) {
            case 1 -> TipoContable.CARGO;
            case 2 -> TipoContable.ABONO;
            default -> TipoContable.NO_CONTABLE;
        };
    }
    return TipoContable.NINGUNO;                // AS-EDOCTA = 5: no va a estado de cuenta
}

/** 150-085-VERIFICA-CVE: ¿se graba en el archivo S050? */
boolean vaAEstadoCuenta(TipoContable tipo, MovimientoLog151 m, int sistema) {
    if (tipo == TipoContable.NINGUNO) return false;          // NOT W88-VALIDO
    if (m.indEdocta() == 1) {
        return sistema != 500 || m.contrato() > 1;           // 500 exige contrato mayor a 1
    }
    return sistema == 407 && m.sistOrig() == 500 && m.contrato() > 1;
}

/** 150-100-GRABA-MOVS dentro de un ClassifierCompositeItemWriter. */
@Bean
ClassifierCompositeItemWriter<RegistroS050> escritorS050(
        FlatFileItemWriter<RegistroS050> movsxcont,
        FlatFileItemWriter<RegistroS050> movsxcont500,
        FlatFileItemWriter<RegistroS050> movsxcontCheq) {
    var w = new ClassifierCompositeItemWriter<RegistroS050>();
    w.setClassifier(r -> switch (r.destino()) {
        case MOVSXCONT      -> movsxcont;      // producto 66 (cuenta maestra)
        case MOVSXCONT_500  -> movsxcont500;   // resto de productos del sistema 500
        case MOVSXCONT_CHEQ -> movsxcontCheq;  // producto 1 del sistema 500
    });
    return w;
}

/** Totales del trailer A00-R02-S050-TRAILER, uno por archivo. 9(16)V99 -> escala 2. */
public final class TotalesS050 {
    private final Map<Destino, long[]> registros = new EnumMap<>(Destino.class);
    private final Map<Destino, BigDecimal> importes = new EnumMap<>(Destino.class);

    public void suma(Destino d, BigDecimal importe) {
        registros.computeIfAbsent(d, k -> new long[1])[0]++;
        importes.merge(d, importe, BigDecimal::add);   // suma exacta de escala 2
    }
}

/** 150-091-PREG-CUENTA-TESOFE: además de MOVSXCONTCHEQ, ¿va a S502 o a S701? */
@Component
@RequiredArgsConstructor
public class TesofeRouter {

    private final P158Properties props;            // csis-tesofe: [10, 32]
    private final List<ServicioTesofe> catalogo;   // cat. 766 de S080, filtrado por "TESOF"

    public Optional<Destino> destino(MovimientoLog151 m, int csi) {
        if (!props.csisTesofe().contains(csi)) return Optional.empty();
        for (ServicioTesofe s : catalogo) {          // la tabla viene ordenada por índice
            if (!"TESOF".equals(s.nombreAbreviado()) || (s.indServ() != 50 && s.indServ() != 51)) {
                return Optional.empty();             // MOVE 100 TO WKS-INDICE-3: corta el barrido
            }
            // Ojo: el servicio 50 compara la sucursal-cuenta contra A00-R01-NUMMDA y el 51
            // contra WKS-CAT-NUMMDA. Se conserva la diferencia hasta que el SME la confirme.
            String cuentaMda = (s.indServ() == 50) ? m.numMda() : m.catNumMda();
            boolean coincide = (s.contrato().equals(m.contrato()) || s.sucCuenta().equals(cuentaMda))
                    && s.producto() == m.producto() && s.instrumento() == m.instrumento();
            if (coincide) {
                return Optional.of(s.indServ() == 50 ? Destino.MOVSXCONT_ESOF     // S502 IMPUESTOS
                                                     : Destino.MOVSXCONT_ESOF2);  // S701 PAGOS
            }
        }
        return Optional.empty();
    }
}
